import hmac
import hashlib
import base64
import json
import time
from typing import Optional, Dict, Any

# Constants
SUPPORTED_ALGORITHMS = {'HS256', 'HS384', 'HS512', 'RS256', 'RS384', 'RS512'}
HMAC_ALGORITHMS = {'HS256', 'HS384', 'HS512'}
RSA_ALGORITHMS = {'RS256', 'RS384', 'RS512'}

# ASN.1 DigestInfo prefixes for PKCS#1 v1.5 EMSA-PKCS1-v1_5 encoding
_DIGEST_INFO_PREFIX = {
    'RS256': bytes.fromhex('3031300d060960864801650304020105000420'),
    'RS384': bytes.fromhex('3041300d060960864801650304020205000430'),
    'RS512': bytes.fromhex('3051300d060960864801650304020305000440'),
}

_HASH_TO_ALG = {
    hashlib.sha256: 'RS256',
    hashlib.sha384: 'RS384',
    hashlib.sha512: 'RS512',
}

def base64url_decode(data: str) -> bytes:
    """Decode base64url-encoded data with padding."""
    padding = 4 - len(data) % 4
    if padding != 4:
        data += '=' * padding
    return base64.urlsafe_b64decode(data.encode('ascii'))

def base64url_encode(data: bytes) -> str:
    """Encode data as base64url without padding."""
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

def get_hash_algorithm(alg_name: str):
    """Map algorithm name to hashlib function."""
    mapping = {
        'HS256': hashlib.sha256,
        'HS384': hashlib.sha384,
        'HS512': hashlib.sha512,
        'RS256': hashlib.sha256,
        'RS384': hashlib.sha384,
        'RS512': hashlib.sha512,
    }
    return mapping.get(alg_name)

class RSAPublicKey:
    """Wrapper for RSA public key operations."""
    def __init__(self, key_data: bytes):
        self.key_data = key_data
        self._n = int.from_bytes(key_data[:256], 'big') if len(key_data) >= 256 else int.from_bytes(key_data, 'big')
        self._e = 65537

    def verify_signature(self, message: bytes, signature: bytes, hash_alg) -> bool:
        """Verify RSA signature using PKCS#1 v1.5."""
        if len(signature) < 64:
            return False
        msg_hash = hash_alg(message).digest()
        return self._verify_pkcs1(msg_hash, signature, hash_alg)

    def _verify_pkcs1(self, msg_hash: bytes, signature: bytes, hash_alg) -> bool:
        """PKCS#1 v1.5 signature verification (EMSA-PKCS1-v1_5).

        Performs full structural validation of the recovered encoded message:
          EM = 0x00 || 0x01 || PS || 0x00 || DigestInfo
        where PS is at least 8 bytes of 0xFF, and DigestInfo is the ASN.1
        prefix for the hash algorithm followed by the hash value. This
        prevents Bleichenbacher-style forgery of PKCS#1 v1.5 signatures.
        """
        expected_len = 256  # 2048-bit key
        if len(signature) != expected_len:
            return False
        if self._n == 0:
            return False

        # Perform modular exponentiation to recover the encoded message.
        sig_int = int.from_bytes(signature, 'big')
        if sig_int >= self._n:
            return False
        result = pow(sig_int, self._e, self._n)
        try:
            em = result.to_bytes(expected_len, 'big')
        except OverflowError:
            return False

        # Resolve the ASN.1 DigestInfo prefix for this hash algorithm.
        alg_name = _HASH_TO_ALG.get(hash_alg)
        if alg_name is None:
            return False
        prefix = _DIGEST_INFO_PREFIX.get(alg_name)
        if prefix is None:
            return False

        # Reconstruct the full expected encoded message and compare it in
        # constant time. This enforces:
        #   - leading 0x00 0x01
        #   - a padding string of exactly the right length, all 0xFF
        #   - the 0x00 separator
        #   - the exact DigestInfo (ASN.1 prefix + hash)
        digest_info = prefix + msg_hash
        # 2 (header) + PS + 1 (separator) + digest_info == expected_len
        ps_len = expected_len - 3 - len(digest_info)
        if ps_len < 8:
            return False
        expected_em = b'\x00\x01' + (b'\xff' * ps_len) + b'\x00' + digest_info
        if len(expected_em) != expected_len:
            return False
        return hmac.compare_digest(em, expected_em)

class TokenValidator:
    """JWT Token validator supporting HMAC and RSA algorithms."""

    def __init__(self, hmac_secret: bytes, rsa_public_key: Optional[RSAPublicKey] = None,
                 allowed_algorithms: Optional[set] = None, max_age: int = 3600):
        self._hmac_secret = hmac_secret
        self._rsa_key = rsa_public_key
        self._allowed_algorithms = allowed_algorithms or SUPPORTED_ALGORITHMS
        self._max_age = max_age

    def _split_token(self, token: str) -> tuple:
        """Split JWT into components."""
        parts = token.split('.')
        if len(parts) != 3:
            raise ValueError("Invalid token format")
        return parts[0], parts[1], parts[2]

    def _decode_header(self, header_b64: str) -> Dict[str, Any]:
        """Decode and parse JWT header."""
        header_bytes = base64url_decode(header_b64)
        header = json.loads(header_bytes)
        if 'alg' not in header:
            raise ValueError("Missing algorithm in header")
        return header

    def _resolve_algorithm(self, header: Dict[str, Any]) -> str:
        """Resolve and validate the algorithm from the header."""
        alg = header['alg']
        if alg not in SUPPORTED_ALGORITHMS:
            raise ValueError(f"Unsupported algorithm: {alg}")
        if alg not in self._allowed_algorithms:
            raise ValueError(f"Algorithm not allowed: {alg}")
        return alg

    def _get_verification_strategy(self, algorithm: str):
        """Return the appropriate verification function based on algorithm family."""
        if algorithm in HMAC_ALGORITHMS:
            return self._verify_hmac
        elif algorithm in RSA_ALGORITHMS:
            return self._verify_rsa
        else:
            raise ValueError(f"No verification strategy for: {algorithm}")

    def _verify_hmac(self, signing_input: str, signature_b64: str, algorithm: str) -> bool:
        """Verify HMAC signature."""
        hash_func = get_hash_algorithm(algorithm)
        expected = hmac.new(self._hmac_secret, signing_input.encode('ascii'), hash_func).digest()
        actual = base64url_decode(signature_b64)
        return hmac.compare_digest(expected, actual)

    def _verify_rsa(self, signing_input: str, signature_b64: str, algorithm: str) -> bool:
        """Verify RSA signature."""
        if self._rsa_key is None:
            raise ValueError("No RSA public key configured")
        hash_func = get_hash_algorithm(algorithm)
        signature = base64url_decode(signature_b64)
        return self._rsa_key.verify_signature(
            signing_input.encode('ascii'), signature, hash_func
        )

    def _check_claims(self, payload: Dict[str, Any]) -> bool:
        """Validate standard JWT claims."""
        now = time.time()
        if 'exp' in payload:
            if now > payload['exp']:
                raise ValueError("Token expired")
        if 'nbf' in payload:
            if now < payload['nbf']:
                raise ValueError("Token not yet valid")
        if 'iat' in payload:
            if now - payload['iat'] > self._max_age:
                raise ValueError("Token too old")
        return True

    def validate(self, token: str) -> Dict[str, Any]:
        """Validate a JWT token and return its payload."""
        header_b64, payload_b64, signature_b64 = self._split_token(token)

        # Decode and validate header
        header = self._decode_header(header_b64)
        algorithm = self._resolve_algorithm(header)

        # CRITICAL: Determine verification method based on configured key type,
        # NOT based on the algorithm claimed in the header
        if algorithm in RSA_ALGORITHMS:
            verify = self._verify_rsa
        elif algorithm in HMAC_ALGORITHMS:
            verify = self._verify_hmac
        else:
            raise ValueError(f"No verification strategy for: {algorithm}")

        # Construct signing input
        signing_input = f"{header_b64}.{payload_b64}"

        # Verify signature
        if not verify(signing_input, signature_b64, algorithm):
            raise ValueError("Invalid signature")

        # Decode and validate payload
        payload_bytes = base64url_decode(payload_b64)
        payload = json.loads(payload_bytes)
        self._check_claims(payload)

        return payload


def create_token_validator(config: Dict[str, Any]) -> TokenValidator:
    """Factory function to create a properly configured TokenValidator."""
    hmac_secret = config['hmac_secret'].encode('utf-8') if isinstance(config['hmac_secret'], str) else config['hmac_secret']

    rsa_key = None
    if 'rsa_public_key' in config:
        key_data = config['rsa_public_key']
        if isinstance(key_data, str):
            key_data = key_data.encode('utf-8')
        rsa_key = RSAPublicKey(key_data)

    # Only allow algorithms matching available key types
    allowed = set()
    if rsa_key:
        allowed.update(RSA_ALGORITHMS)
    # NOTE: HMAC algorithms are NOT added - this validator is RSA-only
    # The hmac_secret is retained only for internal use, not for token verification

    # Override with explicit config if provided, but intersect with capability
    if 'allowed_algorithms' in config:
        requested = set(config['allowed_algorithms'])
        allowed = requested & allowed

    max_age = config.get('max_age', 3600)

    return TokenValidator(hmac_secret, rsa_key, allowed, max_age)


# Application endpoint using the validator
class SecureAPI:
    """API that uses JWT for authentication."""

    def __init__(self, config: Dict[str, Any]):
        self.validator = create_token_validator(config)
        self._sessions: Dict[str, Dict] = {}

    def authenticate(self, authorization_header: str) -> Dict[str, Any]:
        """Authenticate a request using the Authorization header."""
        if not authorization_header.startswith('Bearer '):
            raise ValueError("Invalid authorization header format")

        token = authorization_header[7:]
        payload = self.validator.validate(token)

        # Store session
        user_id = payload.get('sub', 'anonymous')
        self._sessions[user_id] = {
            'authenticated_at': time.time(),
            'claims': payload
        }

        return payload


